UPDATE "email_template_translations" SET "htmlContent" = CASE
WHEN "emailTemplateId" = 'default_access_request_kam' AND "languageCode" = 'en' THEN '<meta charset="UTF-8"><title>New access request</title><table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Hello {{KAM_NAME}},</h2><p>A new access request is waiting for your review.</p><table width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background-color:#f9fafb;border-collapse:collapse"><tr><td style="padding:10px 14px;font-weight:bold">Name</td><td style="padding:10px 14px">{{APPLICANT_NAME}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold">Email</td><td style="padding:10px 14px">{{APPLICANT_EMAIL}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold">Phone</td><td style="padding:10px 14px">{{APPLICANT_PHONE}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold">Agency</td><td style="padding:10px 14px">{{AGENCY_NAME}}</td></tr></table><p style="color:#666666;font-size:13px">Request reference: {{REQUEST_ID}}</p><p><br>Thank you,<br>The AXPO Team</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. All rights reserved.</td></tr></tbody></table>'
WHEN "emailTemplateId" = 'default_access_request_kam' AND "languageCode" = 'es' THEN '<meta charset="UTF-8"><title>Nueva solicitud de alta</title><table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Hola {{KAM_NAME}},</h2><p>Hay una nueva solicitud de alta pendiente de revisión.</p><table width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background-color:#f9fafb;border-collapse:collapse"><tr><td style="padding:10px 14px;font-weight:bold">Nombre</td><td style="padding:10px 14px">{{APPLICANT_NAME}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold">Email</td><td style="padding:10px 14px">{{APPLICANT_EMAIL}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold">Teléfono</td><td style="padding:10px 14px">{{APPLICANT_PHONE}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold">Agencia</td><td style="padding:10px 14px">{{AGENCY_NAME}}</td></tr></table><p style="color:#666666;font-size:13px">Referencia de la solicitud: {{REQUEST_ID}}</p><p><br>Gracias,<br>El equipo de AXPO</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. Todos los derechos reservados.</td></tr></tbody></table>'
WHEN "emailTemplateId" = 'default_access_request_kam' AND "languageCode" = 'fr' THEN '<meta charset="UTF-8"><title>Nouvelle demande d’accès</title><table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Bonjour {{KAM_NAME}},</h2><p>Une nouvelle demande d’accès est en attente d’examen.</p><table width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background-color:#f9fafb;border-collapse:collapse"><tr><td style="padding:10px 14px;font-weight:bold">Nom</td><td style="padding:10px 14px">{{APPLICANT_NAME}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold">E-mail</td><td style="padding:10px 14px">{{APPLICANT_EMAIL}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold">Téléphone</td><td style="padding:10px 14px">{{APPLICANT_PHONE}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold">Agence</td><td style="padding:10px 14px">{{AGENCY_NAME}}</td></tr></table><p style="color:#666666;font-size:13px">Référence : {{REQUEST_ID}}</p><p><br>Merci,<br>L’équipe AXPO</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. Tous droits réservés.</td></tr></tbody></table>'
WHEN "emailTemplateId" = 'default_access_request_kam' AND "languageCode" = 'pt' THEN '<meta charset="UTF-8"><title>Novo pedido de acesso</title><table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Olá {{KAM_NAME}},</h2><p>Existe um novo pedido de acesso pendente de análise.</p><table width="100%" cellpadding="0" cellspacing="0" style="margin:24px 0;background-color:#f9fafb;border-collapse:collapse"><tr><td style="padding:10px 14px;font-weight:bold">Nome</td><td style="padding:10px 14px">{{APPLICANT_NAME}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold">E-mail</td><td style="padding:10px 14px">{{APPLICANT_EMAIL}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold">Telefone</td><td style="padding:10px 14px">{{APPLICANT_PHONE}}</td></tr><tr><td style="padding:10px 14px;font-weight:bold">Agência</td><td style="padding:10px 14px">{{AGENCY_NAME}}</td></tr></table><p style="color:#666666;font-size:13px">Referência: {{REQUEST_ID}}</p><p><br>Obrigado,<br>A equipa AXPO</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. Todos os direitos reservados.</td></tr></tbody></table>'
WHEN "emailTemplateId" = 'default_access_request_applicant' AND "languageCode" = 'en' THEN '<meta charset="UTF-8"><title>Access request received</title><table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Hello {{APPLICANT_NAME}},</h2><p>We received your request to access the AXPO Offers Simulator.</p><p>Your request is pending review by <strong>{{KAM_NAME}}</strong> for <strong>{{AGENCY_NAME}}</strong>. We will contact you when it has been reviewed.</p><p style="color:#666666;font-size:13px">Request reference: {{REQUEST_ID}}</p><p><br>Thank you,<br>The AXPO Team</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. All rights reserved.</td></tr></tbody></table>'
WHEN "emailTemplateId" = 'default_access_request_applicant' AND "languageCode" = 'es' THEN '<meta charset="UTF-8"><title>Solicitud de alta recibida</title><table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Hola {{APPLICANT_NAME}},</h2><p>Hemos recibido tu solicitud de acceso al Simulador de Ofertas de AXPO.</p><p>Tu solicitud está pendiente de revisión por <strong>{{KAM_NAME}}</strong> para <strong>{{AGENCY_NAME}}</strong>. Contactaremos contigo cuando haya sido revisada.</p><p style="color:#666666;font-size:13px">Referencia de la solicitud: {{REQUEST_ID}}</p><p><br>Gracias,<br>El equipo de AXPO</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. Todos los derechos reservados.</td></tr></tbody></table>'
WHEN "emailTemplateId" = 'default_access_request_applicant' AND "languageCode" = 'fr' THEN '<meta charset="UTF-8"><title>Demande d’accès reçue</title><table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Bonjour {{APPLICANT_NAME}},</h2><p>Nous avons reçu votre demande d’accès au simulateur d’offres AXPO.</p><p>Votre demande est en attente d’examen par <strong>{{KAM_NAME}}</strong> pour <strong>{{AGENCY_NAME}}</strong>. Nous vous contacterons après son examen.</p><p style="color:#666666;font-size:13px">Référence : {{REQUEST_ID}}</p><p><br>Merci,<br>L’équipe AXPO</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. Tous droits réservés.</td></tr></tbody></table>'
WHEN "emailTemplateId" = 'default_access_request_applicant' AND "languageCode" = 'pt' THEN '<meta charset="UTF-8"><title>Pedido de acesso recebido</title><table width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;margin:20px auto;border-collapse:collapse"><tbody><tr><td style="background-color:#f3f3f3;padding:20px;text-align:center"><img src="https://misimulador.axpoiberia.es/axpo-logo.svg" alt="AXPO" width="150"></td></tr><tr><td style="background-color:#ffffff;padding:30px;color:#2d2d2d;line-height:1.6"><h2 style="color:#E91E63;font-size:20px;margin-top:0">Olá {{APPLICANT_NAME}},</h2><p>Recebemos o seu pedido de acesso ao Simulador de Ofertas AXPO.</p><p>O pedido está pendente de análise por <strong>{{KAM_NAME}}</strong> para <strong>{{AGENCY_NAME}}</strong>. Entraremos em contacto após a análise.</p><p style="color:#666666;font-size:13px">Referência: {{REQUEST_ID}}</p><p><br>Obrigado,<br>A equipa AXPO</p></td></tr><tr><td style="background-color:#f9fafb;padding:20px;text-align:center;color:#6b7280;font-size:12px">© {{CURRENT_YEAR}} AXPO Energy Solutions. Todos os direitos reservados.</td></tr></tbody></table>'
ELSE "htmlContent" END,
"updatedAt" = CURRENT_TIMESTAMP
WHERE "emailTemplateId" IN ('default_access_request_kam', 'default_access_request_applicant');

UPDATE "email_templates" template
SET "htmlContent" = translation."htmlContent", "updatedAt" = CURRENT_TIMESTAMP
FROM "email_template_translations" translation
WHERE translation."emailTemplateId" = template."id"
  AND translation."languageCode" = 'en'
  AND template."id" IN ('default_access_request_kam', 'default_access_request_applicant');
